command:
/**
 * SVA example: Bomb Throw
 * Lobs a bomb at every target: it bursts into shrapnel, explodes, and leaves a cracked, smoking
 * patch of ground that fades over a few seconds.
 *
 * Usage: select the thrower, target one or more tokens, run.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const COLOR = "black"; // black, blue, green, grey, red (bomb and shrapnel share colours)
const FILES = {
  bomb: `jb2a.throwable.throw.bomb.01.${COLOR}`,
  shrapnel: `jb2a.explosion.shrapnel.bomb.01.${COLOR}`,
  blast: "jb2a.explosion.08.dark_orange",
  scorch: "jb2a.impact.ground_crack.orange"
};

const thrower = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!thrower) return ui.notifications.warn("Select the throwing token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const runs = [];
for (const target of targets) {
  const seq = SVA.sequence();
  seq.effect().file(FILES.bomb).atLocation(thrower).stretchTo(target).waitUntilFinished(-150);
  seq
    .effect()
    .file(FILES.scorch)
    .atLocation(target)
    .layer("belowTokens")
    .scaleToObject(2)
    .scaleIn(0.1, 120, { ease: "easeOutExpo" })
    .duration(5000)
    .fadeOut(3200, { ease: "easeInSine" });
  seq.effect().file(FILES.shrapnel).atLocation(target).scaleToObject(1.2);
  seq.effect().file(FILES.blast).atLocation(target).scaleToObject(1.8).delay(100);
  runs.push(seq.play());
  await sleep(650 + Math.random() * 350);
}
await Promise.all(runs);
